new_fn = '''def _invlogit(x):
    return 1 / (1 + np.exp(-x))


def compute_ame(result, df, formula_str):
    """Average Marginal Effects for CWM vs CLS, computed analytically."""
    params = result.params
    param_names = list(params.index)
    beta = params.values

    df = df.copy()
    for col in ["formulation", "model", "complexity"]:
        if col in df.columns:
            df[col] = df[col].astype(str)

    ame_results = {}
    if "formulation" not in formula_str:
        return ame_results

    # Build exog manually for CLS and CWM versions of each row
    def _build_exog_row(row, formulation_val):
        x = [1.0]  # Intercept
        is_cwm = 1.0 if formulation_val == "CWM" else 0.0
        x.append(is_cwm)

        if "complexity" in formula_str:
            is_repo = 1.0 if row.get("complexity", "") == "repo" else 0.0
            x.append(is_repo)
            x.append(is_cwm * is_repo)  # interaction
        elif "model" in formula_str:
            is_qwen = 1.0 if row.get("model", "") == "Qwen3-8B" else 0.0
            x.append(is_qwen)
            x.append(is_cwm * is_qwen)  # interaction

        return np.array(x)

    # Compute per-observation AME
    deltas = []
    for _, row in df.iterrows():
        x_cls = _build_exog_row(row, "CLS")
        x_cwm = _build_exog_row(row, "CWM")
        p_cls = _invlogit(x_cls @ beta)
        p_cwm = _invlogit(x_cwm @ beta)
        deltas.append(p_cwm - p_cls)

    ame_results["CWM_vs_CLS_overall"] = round(float(np.mean(deltas)), 4)

    # Subgroup AMEs
    if "complexity" in formula_str:
        for cx in ["function", "repo"]:
            sub = df[df["complexity"] == cx]
            if len(sub) == 0:
                continue
            sub_deltas = []
            for _, row in sub.iterrows():
                x_cls = _build_exog_row(row, "CLS")
                x_cwm = _build_exog_row(row, "CWM")
                sub_deltas.append(_invlogit(x_cwm @ beta) - _invlogit(x_cls @ beta))
            ame_results[f"CWM_vs_CLS_{cx}"] = round(float(np.mean(sub_deltas)), 4)

    if "model" in formula_str:
        for m in df["model"].unique():
            sub = df[df["model"] == m]
            if len(sub) == 0:
                continue
            sub_deltas = []
            for _, row in sub.iterrows():
                x_cls = _build_exog_row(row, "CLS")
                x_cwm = _build_exog_row(row, "CWM")
                sub_deltas.append(_invlogit(x_cwm @ beta) - _invlogit(x_cls @ beta))
            ame_results[f"CWM_vs_CLS_{m}"] = round(float(np.mean(sub_deltas)), 4)

    return ame_results'''

